function(container, apiUrl, tables) {
  const tbody = container.querySelector("#results-tbody");
  let calculationResults = [];

  // 1. テーブル再描画関数を定義
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" class="muted" style="text-align: center; padding: 2rem;">計算結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id || ''}">
        <td><a href="#" class="product-detail-link" data-product-id="${r.商品ID || ''}" style="color: var(--primary); text-decoration: none;">${r.商品名 || ''}</a></td>
        <td>${r.商品コード || ''}</td>
        <td>${r.予測需要量 || 0}</td>
        <td>${r.現在在庫 || 0}</td>
        <td>${r.安全在庫 || 0}</td>
        <td style="font-weight: bold; color: var(--primary);">${r.推奨発注量 || 0}</td>
        <td>${r.発注タイミング || ''}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.id || ''}">詳細</button>
          <button class="action-btn secondary order-btn" data-id="${r.id || ''}">発注</button>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データを即座に描画
  renderRows([]);

  // 店舗データの読み込み
  async function loadStores() {
    const storeSelect = container.querySelector("#store-select");
    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        stores.forEach(store => {
          const option = document.createElement("option");
          option.value = store.店舗ID;
          option.textContent = store.店舗名;
          storeSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error("店舗データの読み込みに失敗しました:", error);
    }
  }

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
    setTimeout(() => {
      errorDiv.classList.add("hidden");
    }, 5000);
  }

  // バリデーション関数
  function validateInputs() {
    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 0;
    const leadTime = parseInt(container.querySelector("#lead-time").value) || 0;
    const orderPoint = parseInt(container.querySelector("#order-point").value) || 0;

    if (!storeId) {
      showError("店舗を選択してください");
      return false;
    }
    if (!category) {
      showError("商品カテゴリを選択してください");
      return false;
    }
    if (!periodStart || !periodEnd) {
      showError("計算対象期間を設定してください");
      return false;
    }
    if (new Date(periodStart) > new Date(periodEnd)) {
      showError("期間の開始日は終了日より前に設定してください");
      return false;
    }
    if (safetyStock < 0) {
      showError("安全在庫数は0以上の値を入力してください");
      return false;
    }
    if (leadTime <= 0) {
      showError("リードタイムは1以上の値を入力してください");
      return false;
    }
    if (orderPoint < 0) {
      showError("発注点は0以上の値を入力してください");
      return false;
    }

    return true;
  }

  // 発注量計算実行
  async function executeCalculation() {
    if (!validateInputs()) return;

    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = parseInt(container.querySelector("#safety-stock").value) || 0;
    const leadTime = parseInt(container.querySelector("#lead-time").value) || 1;
    const orderPoint = parseInt(container.querySelector("#order-point").value) || 0;

    try {
      // 需要予測データ取得
      const forecastData = await window.aivicApi.list(9); // 需要予測結果
      if (!forecastData) {
        showError("需要予測データの取得に失敗しました");
        return;
      }

      // 商品マスタ取得
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (!products) {
        showError("商品データの取得に失敗しました");
        return;
      }

      // 在庫データ取得（売上実績データから推定）
      const salesData = await window.aivicApi.list(3); // 売上実績データ
      if (!salesData) {
        showError("在庫データの取得に失敗しました");
        return;
      }

      // 計算処理
      const filteredProducts = products.filter(p => 
        p.商品カテゴリID && p.商品カテゴリID.includes(category)
      );

      calculationResults = filteredProducts.map(product => {
        // 需要予測データを取得
        const forecast = forecastData.find(f => 
          f.商品ID === product.商品ID && f.店舗ID === storeId
        );
        const predictedDemand = forecast ? forecast.予測数量 : 0;

        // 現在在庫を推定（実際のシステムでは在庫マスタから取得）
        const currentStock = Math.floor(Math.random() * 1000) + 100;

        // 発注量計算
        const demandDuringLeadTime = predictedDemand * leadTime;
        const totalRequirement = demandDuringLeadTime + safetyStock;
        const recommendedOrder = Math.max(0, totalRequirement - currentStock);

        // 発注タイミング判定
        let orderTiming = "発注不要";
        if (currentStock <= orderPoint) {
          orderTiming = "即時発注";
        } else if (currentStock <= orderPoint + (predictedDemand * 3)) {
          orderTiming = "3日以内";
        } else if (currentStock <= orderPoint + (predictedDemand * 7)) {
          orderTiming = "1週間以内";
        }

        return {
          id: product.商品ID,
          商品ID: product.商品ID,
          商品名: product.商品名,
          商品コード: product.商品コード,
          予測需要量: predictedDemand,
          現在在庫: currentStock,
          安全在庫: safetyStock,
          推奨発注量: recommendedOrder,
          発注タイミング: orderTiming
        };
      });

      // 結果表示更新
      renderRows(calculationResults);

      // 需要予測結果表示更新
      const forecastDisplay = container.querySelector("#forecast-display");
      const totalDemand = calculationResults.reduce((sum, r) => sum + r.予測需要量, 0);
      forecastDisplay.innerHTML = `
        <h4>需要予測サマリー</h4>
        <p>対象商品数: ${calculationResults.length}品目</p>
        <p>総予測需要量: ${totalDemand}個</p>
        <p>計算期間: ${periodStart} ～ ${periodEnd}</p>
      `;

      // 設定値表示更新
      container.querySelector("#current-stock").textContent = 
        calculationResults.reduce((sum, r) => sum + r.現在在庫, 0).toLocaleString();
      container.querySelector("#display-safety-stock").textContent = safetyStock.toLocaleString();
      container.querySelector("#display-lead-time").textContent = `${leadTime}日`;
      container.querySelector("#display-order-point").textContent = orderPoint.toLocaleString();

    } catch (error) {
      console.error("計算処理でエラーが発生しました:", error);
      showError("計算処理中にエラーが発生しました");
    }
  }

  // 3. 検索ボタンのイベントリスナー
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    if (!keyword) {
      renderRows(calculationResults);
      return;
    }

    const filtered = calculationResults.filter(r => 
      (r.商品名 || "").toLowerCase().includes(keyword) ||
      (r.商品コード || "").toLowerCase().includes(keyword)
    );
    renderRows(filtered);
  });

  // 計算実行ボタン
  container.querySelector("#btn-calculate").addEventListener("click", executeCalculation);

  // 条件クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#store-select").value = "";
    container.querySelector("#category-select").value = "";
    container.querySelector("#period-start").value = "";
    container.querySelector("#period-end").value = "";
    container.querySelector("#safety-stock").value = "";
    container.querySelector("#lead-time").value = "";
    container.querySelector("#order-point").value = "";

    // 表示リセット
    container.querySelector("#forecast-display").innerHTML = 
      '<p class="muted">計算条件を設定して「計算実行」ボタンをクリックしてください。</p>';
    container.querySelector("#current-stock").textContent = "-";
    container.querySelector("#display-safety-stock").textContent = "-";
    container.querySelector("#display-lead-time").textContent = "-";
    container.querySelector("#display-order-point").textContent = "-";

    calculationResults = [];
    renderRows([]);
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-export").addEventListener("click", () => {
    if (calculationResults.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品名", "商品コード", "予測需要量", "現在在庫", "安全在庫", "推奨発注量", "発注タイミング"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...calculationResults.map(r => [
        `"${r.商品名 || ""}"`,
        `"${r.商品コード || ""}"`,
        r.予測需要量 || 0,
        r.現在在庫 || 0,
        r.安全在庫 || 0,
        r.推奨発注量 || 0,
        `"${r.発注タイミング || ""}"`
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 5. 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 商品詳細リンク
    const productLink = e.target.closest(".product-detail-link");
    if (productLink) {
      e.preventDefault();
      // 商品詳細画面への遷移（実装されている場合）
      // window.showScreen("product-detail-screen");
      return;
    }

    // 詳細ボタン
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const result = calculationResults.find(r => r.id === id);
      if (result) {
        alert(`商品詳細\n商品名: ${result.商品名}\n予測需要量: ${result.予測需要量}\n推奨発注量: ${result.推奨発注量}`);
      }
      return;
    }

    // 発注ボタン
    const orderBtn = e.target.closest(".order-btn");
    if (orderBtn) {
      const id = orderBtn.dataset.id;
      const result = calculationResults.find(r => r.id === id);
      if (result && confirm(`${result.商品名}を${result.推奨発注量}個発注しますか？`)) {
        // 発注データ作成
        const orderData = {
          店舗ID: container.querySelector("#store-select").value,
          商品ID: result.商品ID,
          発注日: new Date().toISOString(),
          納期予定日: new Date(Date.now() + parseInt(container.querySelector("#lead-time").value || 7) * 24 * 60 * 60 * 1000).toISOString(),
          発注数量: result.推奨発注量,
          予測数量: result.予測需要量,
          発注単価: 100, // 仮の単価
          発注金額: result.推奨発注量 * 100,
          発注方法: "AI推奨採用",
          発注ステータス: "発注済",
          仕入先ID: "default-supplier",
          発注理由: "AI需要予測による自動発注",
          自動発注フラグ: true,
          作成者ID: "current-user",
          更新者ID: "current-user"
        };

        const saved = await window.aivicApi.save(10, orderData); // 発注データ
        if (saved) {
          alert("発注が完了しました");
          // 発注管理画面への遷移
          window.showScreen("scr-1778591852463");
        }
      }
      return;
    }
  });

  // 初期化時に店舗データを読み込み
  loadStores();

  // デフォルト値設定
  const today = new Date();
  const nextWeek = new Date(today.getTime() + 7 * 24 * 60 * 60 * 1000);
  container.querySelector("#period-start").value = today.toISOString().split('T')[0];
  container.querySelector("#period-end").value = nextWeek.toISOString().split('T')[0];
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#inventory-tbody");
  const errorMessage = container.querySelector("#error-message");
  const searchResultMessage = container.querySelector("#search-result-message");
  const storeSelect = container.querySelector("#store-select");

  // 店舗マスタのテーブルインデックスを取得
  const storeTableIndex = tables.findIndex(t => t.tableName === "店舗マスタ");
  const productTableIndex = tables.findIndex(t => t.tableName === "商品マスタ");

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // バリデーション関数
  function validateInput() {
    const productName = container.querySelector("#product-name-search").value;
    const productCode = container.querySelector("#product-code-search").value;

    // 商品名の特殊文字チェック
    if (productName && /<script|javascript:|data:|vbscript:|onload=|onerror=/i.test(productName)) {
      showError("商品名に不正な文字が含まれています");
      return false;
    }

    // SQLインジェクション対策
    if (productName && /('|"|;|--|\/\*|\*\/|xp_|sp_|DROP|DELETE|INSERT|UPDATE|SELECT)/i.test(productName)) {
      showError("商品名に使用できない文字が含まれています");
      return false;
    }

    // 商品コードの数値チェック（文字が入力された場合）
    if (productCode && !/^\d*$/.test(productCode)) {
      showError("商品コードは数値で入力してください");
      return false;
    }

    // 商品名の最大文字数チェック
    if (productName && productName.length > 255) {
      showError("商品名は255文字以内で入力してください");
      return false;
    }

    // 商品コードの最大桁数チェック
    if (productCode && productCode.length > 20) {
      showError("商品コードは20桁以内で入力してください");
      return false;
    }

    return true;
  }

  // 在庫状況判定関数
  function getStockStatus(currentStock, safetyStock) {
    if (currentStock === 0) return "不足";
    if (currentStock <= safetyStock) return "不足";
    if (currentStock > safetyStock * 2) return "過剰";
    return "適正";
  }

  // 在庫状況の色分け
  function getStatusColor(status) {
    switch (status) {
      case "不足": return "color: #ff6a6a;";
      case "過剰": return "color: #ffa500;";
      case "適正": return "color: #4caf50;";
      default: return "color: var(--text);";
    }
  }

  // テーブル再描画関数
  function renderRows(inventoryData) {
    if (!inventoryData || inventoryData.length === 0) {
      tbody.innerHTML = "";
      searchResultMessage.textContent = "該当する商品が見つかりませんでした";
      return;
    }

    tbody.innerHTML = inventoryData.map(item => {
      const status = getStockStatus(item.currentStock || 0, item.safetyStock || 0);
      const statusStyle = getStatusColor(status);

      return `
        <tr data-id="${item.id || ''}">
          <td>${item.productCode || ""}</td>
          <td>${item.productName || ""}</td>
          <td>${item.category || ""}</td>
          <td style="${item.currentStock === 0 ? 'color: #ff6a6a; font-weight: bold;' : ''}">${item.currentStock || 0}</td>
          <td>${item.safetyStock || 0}</td>
          <td style="${statusStyle}">${status}</td>
          <td>${item.lastUpdated ? new Date(item.lastUpdated).toLocaleString() : ""}</td>
        </tr>
      `;
    }).join("");

    searchResultMessage.textContent = `${inventoryData.length}件の商品が見つかりました`;
  }

  // 店舗選択肢を設定
  async function loadStores() {
    if (storeTableIndex >= 0) {
      const stores = await window.aivicApi.list(storeTableIndex);
      if (stores) {
        stores.filter(store => store.有効フラグ).forEach(store => {
          const option = document.createElement("option");
          option.value = store.店舗ID;
          option.textContent = `${store.店舗コード} - ${store.店舗名}`;
          storeSelect.appendChild(option);
        });
      }
    }
  }

  // 在庫データ生成（サンプルデータ）
  function generateInventoryData(products, selectedStoreId) {
    return products.map(product => ({
      id: product.商品ID,
      productCode: product.商品コード,
      productName: product.商品名,
      category: getCategoryName(product.商品カテゴリID),
      currentStock: Math.floor(Math.random() * 200),
      safetyStock: Math.floor(Math.random() * 50) + 10,
      lastUpdated: new Date(Date.now() - Math.random() * 7 * 24 * 60 * 60 * 1000).toISOString()
    }));
  }

  function getCategoryName(categoryId) {
    const categories = {
      "cat1": "食品",
      "cat2": "日用品", 
      "cat3": "衣料品",
      "cat4": "家電"
    };
    return categories[categoryId] || "その他";
  }

  // 検索実行
  async function performSearch() {
    const selectedStoreId = storeSelect.value;

    if (!selectedStoreId) {
      showError("店舗を選択してください");
      return;
    }

    if (!validateInput()) {
      return;
    }

    const categoryFilter = container.querySelector("#category-filter").value;
    const productNameSearch = container.querySelector("#product-name-search").value.toLowerCase();
    const productCodeSearch = container.querySelector("#product-code-search").value;
    const stockStatusFilter = container.querySelector("#stock-status-filter").value;

    try {
      // 商品マスタを取得
      const products = await window.aivicApi.list(productTableIndex);
      if (!products) {
        showError("商品データの取得に失敗しました");
        return;
      }

      // 在庫データを生成
      let inventoryData = generateInventoryData(products.filter(p => p.有効フラグ), selectedStoreId);

      // フィルタリング
      if (categoryFilter) {
        inventoryData = inventoryData.filter(item => item.category === categoryFilter);
      }

      if (productNameSearch) {
        inventoryData = inventoryData.filter(item => 
          item.productName.toLowerCase().includes(productNameSearch)
        );
      }

      if (productCodeSearch) {
        inventoryData = inventoryData.filter(item => 
          item.productCode.includes(productCodeSearch)
        );
      }

      if (stockStatusFilter) {
        inventoryData = inventoryData.filter(item => {
          const status = getStockStatus(item.currentStock, item.safetyStock);
          return status === stockStatusFilter;
        });
      }

      renderRows(inventoryData);

    } catch (error) {
      showError("検索処理中にエラーが発生しました");
      console.error("Search error:", error);
    }
  }

  // CSVエクスポート
  function exportToCSV() {
    const selectedStoreId = storeSelect.value;
    if (!selectedStoreId) {
      showError("店舗を選択してください");
      return;
    }

    window.aivicApi.list(productTableIndex).then(products => {
      if (!products) return;

      const inventoryData = generateInventoryData(products.filter(p => p.有効フラグ), selectedStoreId);

      const headers = ["商品コード", "商品名", "商品カテゴリ", "現在在庫数", "安全在庫数", "在庫状況", "最終更新日時"];
      const csvContent = [
        headers.join(","),
        ...inventoryData.map(item => {
          const status = getStockStatus(item.currentStock, item.safetyStock);
          return [
            `"${item.productCode}"`,
            `"${item.productName}"`,
            `"${item.category}"`,
            item.currentStock,
            item.safetyStock,
            `"${status}"`,
            `"${new Date(item.lastUpdated).toLocaleString()}"`
          ].join(",");
        })
      ].join("\n");

      const bom = "\uFEFF";
      const blob = new Blob([bom + csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `在庫一覧_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 検索条件クリア
  function clearSearchConditions() {
    container.querySelector("#category-filter").value = "";
    container.querySelector("#product-name-search").value = "";
    container.querySelector("#product-code-search").value = "";
    container.querySelector("#stock-status-filter").value = "";
    tbody.innerHTML = "";
    searchResultMessage.textContent = "";
    errorMessage.classList.add("hidden");
  }

  // 初期化
  loadStores();
  renderRows([]);

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", performSearch);
  container.querySelector("#btn-clear").addEventListener("click", clearSearchConditions);
  container.querySelector("#btn-export").addEventListener("click", exportToCSV);

  // Enterキーで検索実行
  container.addEventListener("keypress", (e) => {
    if (e.key === "Enter") {
      performSearch();
    }
  });
}

function(container, apiUrl, tables) {
  let currentData = [];
  let sortColumn = '';
  let sortDirection = 'asc';

  // 店舗選択肢を初期化
  function initStoreOptions() {
    const storeSelect = container.querySelector('#store-filter');
    const stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];
    stores.forEach(store => {
      const option = document.createElement('option');
      option.value = store.店舗ID;
      option.textContent = store.店舗名;
      storeSelect.appendChild(option);
    });
  }

  // 予測精度データの再描画
  function renderRows(rows) {
    const tbody = container.querySelector('#accuracy-tbody');
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = rows.map((row, index) => {
      const store = tables.find(t => t.tableName === '店舗マスタ')?.records?.find(s => s.店舗ID === row.店舗ID);
      const product = tables.find(t => t.tableName === '商品マスタ')?.records?.find(p => p.商品ID === row.商品ID);
      const mape = calculateMAPE(row.予測数量, row.実績数量);
      const rmse = calculateRMSE(row.予測数量, row.実績数量);
      const accuracy = Math.max(0, 100 - mape);

      return `
        <tr data-id="${row.予測結果ID}">
          <td>${index + 1}</td>
          <td>${store?.店舗名 || '不明'}</td>
          <td>${product?.商品名 || '不明'}</td>
          <td>${mape.toFixed(2)}%</td>
          <td>${rmse.toFixed(2)}</td>
          <td style="color: ${accuracy >= 80 ? '#4ade80' : accuracy >= 60 ? '#fbbf24' : '#f87171'}">${accuracy.toFixed(1)}%</td>
          <td>${new Date(row.予測対象日).toLocaleDateString()}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${row.予測結果ID}">詳細分析</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // MAPE計算
  function calculateMAPE(predicted, actual) {
    if (!actual || actual === 0) return 0;
    return Math.abs((actual - predicted) / actual) * 100;
  }

  // RMSE計算
  function calculateRMSE(predicted, actual) {
    return Math.sqrt(Math.pow(actual - predicted, 2));
  }

  // グラフ描画
  function drawAccuracyChart() {
    const canvas = container.querySelector('#accuracy-chart');
    const ctx = canvas.getContext('2d');

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = 50;

    // 背景
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(0, 0, width, height);

    // サンプルデータ
    const data = [
      { date: '1/1', mape: 18.5, rmse: 9.2 },
      { date: '1/8', mape: 16.8, rmse: 8.7 },
      { date: '1/15', mape: 15.2, rmse: 8.1 },
      { date: '1/22', mape: 14.9, rmse: 7.8 },
      { date: '1/29', mape: 15.8, rmse: 8.3 }
    ];

    // 軸
    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // MAPE線グラフ
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((point, i) => {
      const x = padding + (i * (width - padding * 2) / (data.length - 1));
      const y = height - padding - ((point.mape / 25) * (height - padding * 2));
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('MAPE推移', padding, 20);
  }

  function drawComparisonChart() {
    const canvas = container.querySelector('#comparison-chart');
    const ctx = canvas.getContext('2d');

    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * window.devicePixelRatio;
    canvas.height = rect.height * window.devicePixelRatio;
    ctx.scale(window.devicePixelRatio, window.devicePixelRatio);

    const width = rect.width;
    const height = rect.height;
    const padding = 50;

    // 背景
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(0, 0, width, height);

    // サンプルデータ
    const data = [
      { date: '1/1', predicted: 120, actual: 115 },
      { date: '1/2', predicted: 135, actual: 142 },
      { date: '1/3', predicted: 98, actual: 89 },
      { date: '1/4', predicted: 156, actual: 148 },
      { date: '1/5', predicted: 178, actual: 185 }
    ];

    // 軸
    ctx.strokeStyle = '#475569';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, height - padding);
    ctx.lineTo(width - padding, height - padding);
    ctx.stroke();

    // 予測値線
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((point, i) => {
      const x = padding + (i * (width - padding * 2) / (data.length - 1));
      const y = height - padding - ((point.predicted / 200) * (height - padding * 2));
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 実績値線
    ctx.strokeStyle = '#10b981';
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach((point, i) => {
      const x = padding + (i * (width - padding * 2) / (data.length - 1));
      const y = height - padding - ((point.actual / 200) * (height - padding * 2));
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '12px sans-serif';
    ctx.fillText('予測値', padding, 20);
    ctx.fillText('実績値', padding + 60, 20);
  }

  // ソート機能
  function sortData(column) {
    if (sortColumn === column) {
      sortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    } else {
      sortColumn = column;
      sortDirection = 'asc';
    }

    currentData.sort((a, b) => {
      let aVal, bVal;

      switch(column) {
        case 'rank':
          return 0; // 順位は固定
        case 'store_name':
          const storeA = tables.find(t => t.tableName === '店舗マスタ')?.records?.find(s => s.店舗ID === a.店舗ID);
          const storeB = tables.find(t => t.tableName === '店舗マスタ')?.records?.find(s => s.店舗ID === b.店舗ID);
          aVal = storeA?.店舗名 || '';
          bVal = storeB?.店舗名 || '';
          break;
        case 'product_name':
          const productA = tables.find(t => t.tableName === '商品マスタ')?.records?.find(p => p.商品ID === a.商品ID);
          const productB = tables.find(t => t.tableName === '商品マスタ')?.records?.find(p => p.商品ID === b.商品ID);
          aVal = productA?.商品名 || '';
          bVal = productB?.商品名 || '';
          break;
        case 'mape':
          aVal = calculateMAPE(a.予測数量, a.実績数量);
          bVal = calculateMAPE(b.予測数量, b.実績数量);
          break;
        case 'rmse':
          aVal = calculateRMSE(a.予測数量, a.実績数量);
          bVal = calculateRMSE(b.予測数量, b.実績数量);
          break;
        case 'accuracy':
          aVal = Math.max(0, 100 - calculateMAPE(a.予測数量, a.実績数量));
          bVal = Math.max(0, 100 - calculateMAPE(b.予測数量, b.実績数量));
          break;
        case 'period':
          aVal = new Date(a.予測対象日);
          bVal = new Date(b.予測対象日);
          break;
        default:
          return 0;
      }

      if (typeof aVal === 'string') {
        return sortDirection === 'asc' ? aVal.localeCompare(bVal) : bVal.localeCompare(aVal);
      } else {
        return sortDirection === 'asc' ? aVal - bVal : bVal - aVal;
      }
    });

    // ソートインジケーター更新
    container.querySelectorAll('.sort-indicator').forEach(indicator => {
      indicator.textContent = '↕';
    });
    const activeHeader = container.querySelector(`[data-sort="${column}"] .sort-indicator`);
    if (activeHeader) {
      activeHeader.textContent = sortDirection === 'asc' ? '↑' : '↓';
    }

    renderRows(currentData);
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  function hideError() {
    container.querySelector('#error-message').classList.add('hidden');
  }

  // CSVエクスポート
  function exportCSV() {
    if (!currentData || currentData.length === 0) {
      alert('エクスポートするデータがありません');
      return;
    }

    const headers = ['順位', '店舗名', '商品名', 'MAPE', 'RMSE', '精度', '期間'];
    const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
      currentData.map((row, index) => {
        const store = tables.find(t => t.tableName === '店舗マスタ')?.records?.find(s => s.店舗ID === row.店舗ID);
        const product = tables.find(t => t.tableName === '商品マスタ')?.records?.find(p => p.商品ID === row.商品ID);
        const mape = calculateMAPE(row.予測数量, row.実績数量);
        const rmse = calculateRMSE(row.予測数量, row.実績数量);
        const accuracy = Math.max(0, 100 - mape);

        return [
          index + 1,
          `"${store?.店舗名 || '不明'}"`,
          `"${product?.商品名 || '不明'}"`,
          `${mape.toFixed(2)}%`,
          rmse.toFixed(2),
          `${accuracy.toFixed(1)}%`,
          new Date(row.予測対象日).toLocaleDateString()
        ].join(',');
      }).join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `予測精度レポート_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  initStoreOptions();

  // 初期データ読み込み
  window.aivicApi.list(4).then(rows => {
    if (rows) {
      currentData = rows;
      renderRows(rows);
      hideError();
    } else {
      showError('データの取得に失敗しました。ネットワーク接続を確認してください。');
    }
  });

  // グラフ描画
  setTimeout(() => {
    drawAccuracyChart();
    drawComparisonChart();
  }, 100);

  // 検索機能
  container.querySelector('#btn-search').addEventListener('click', async () => {
    const period = container.querySelector('#period-filter').value;
    const storeId = container.querySelector('#store-filter').value;
    const category = container.querySelector('#category-filter').value;
    const keyword = container.querySelector('#input-search').value;

    try {
      const rows = await window.aivicApi.list(4);
      if (rows) {
        let filtered = rows;

        // 期間フィルター
        const cutoffDate = new Date();
        cutoffDate.setDate(cutoffDate.getDate() - parseInt(period));
        filtered = filtered.filter(row => new Date(row.予測対象日) >= cutoffDate);

        // 店舗フィルター
        if (storeId) {
          filtered = filtered.filter(row => row.店舗ID === storeId);
        }

        // カテゴリフィルター
        if (category) {
          const categoryProducts = tables.find(t => t.tableName === '商品マスタ')?.records?.filter(p => p.商品カテゴリ === category) || [];
          const categoryProductIds = categoryProducts.map(p => p.商品ID);
          filtered = filtered.filter(row => categoryProductIds.includes(row.商品ID));
        }

        // キーワード検索
        if (keyword) {
          filtered = filtered.filter(row => {
            const store = tables.find(t => t.tableName === '店舗マスタ')?.records?.find(s => s.店舗ID === row.店舗ID);
            const product = tables.find(t => t.tableName === '商品マスタ')?.records?.find(p => p.商品ID === row.商品ID);
            return (store?.店舗名 || '').includes(keyword) || (product?.商品名 || '').includes(keyword);
          });
        }

        currentData = filtered;
        renderRows(filtered);
        hideError();
      } else {
        showError('データの取得に失敗しました。');
      }
    } catch (error) {
      showError('検索中にエラーが発生しました。');
    }
  });

  // エクスポート機能
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // 再試行機能
  container.querySelector('#btn-retry').addEventListener('click', async () => {
    const rows = await window.aivicApi.list(4);
    if (rows) {
      currentData = rows;
      renderRows(rows);
      hideError();
    }
  });

  // ソート機能
  container.addEventListener('click', (e) => {
    const sortHeader = e.target.closest('.sortable');
    if (sortHeader) {
      const column = sortHeader.dataset.sort;
      sortData(column);
    }

    // 詳細分析ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      window.showScreen('scr-1778591838939');
    }
  });

  // オフライン検知
  window.addEventListener('offline', () => {
    showError('ネットワークに接続できません。接続を確認してください。');
  });

  window.addEventListener('online', () => {
    hideError();
  });
}

function(container, apiUrl, tables) {
  // テスト履歴データのテーブルインデックスを特定
  let testHistoryTableIndex = -1;
  for (let i = 0; i < tables.length; i++) {
    if (tables[i].tableName && tables[i].tableName.includes('テスト履歴')) {
      testHistoryTableIndex = i;
      break;
    }
  }

  // テスト履歴がない場合は適当なテーブルを使用（デモ用）
  if (testHistoryTableIndex === -1) {
    testHistoryTableIndex = 0;
  }

  // 1. テスト履歴再描画関数の定義
  function renderTestHistory(rows) {
    const tbody = container.querySelector("#test-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id || ''}">
        <td>${r.テスト日時 || r.作成日時 || '-'}</td>
        <td>${r.モデル名 || r.予測モデルバージョン || '-'}</td>
        <td>${r.テスト期間 || '-'}</td>
        <td>${r.対象店舗数 || '1'}</td>
        <td>${r.MAPE || '-'}%</td>
        <td>${r.RMSE || '-'}</td>
        <td>${r.実行時間 || '-'}秒</td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${r.id || ''}">詳細</button>
        </td>
      </tr>
    `).join("");
  }

  // 2. 初期データを即座に描画
  renderTestHistory(tables[testHistoryTableIndex]?.records || []);

  // 3. 全店舗選択チェックボックスの処理
  const selectAllStores = container.querySelector("#select-all-stores");
  const storeCheckboxes = container.querySelectorAll('input[name="stores"]');

  selectAllStores.addEventListener("change", function() {
    storeCheckboxes.forEach(cb => {
      cb.checked = this.checked;
    });
  });

  // 4. 全カテゴリ選択チェックボックスの処理
  const selectAllCategories = container.querySelector("#select-all-categories");
  const categoryCheckboxes = container.querySelectorAll('input[name="categories"]');

  selectAllCategories.addEventListener("change", function() {
    categoryCheckboxes.forEach(cb => {
      cb.checked = this.checked;
    });
  });

  // 5. テスト実行ボタンの処理
  container.querySelector("#btn-test-execute").addEventListener("click", async function() {
    const model = container.querySelector("#select-model").value;
    const startDate = container.querySelector("#input-start-date").value;
    const endDate = container.querySelector("#input-end-date").value;
    const dataset = container.querySelector('input[name="dataset"]:checked')?.value;
    const selectedStores = Array.from(container.querySelectorAll('input[name="stores"]:checked')).map(cb => cb.value);
    const selectedCategories = Array.from(container.querySelectorAll('input[name="categories"]:checked')).map(cb => cb.value);

    // バリデーション
    if (!model) {
      alert("モデルが選択されていません。モデルを選択してください。");
      return;
    }

    if (!dataset) {
      alert("テストデータセットが選択されていません");
      return;
    }

    if (!startDate || !endDate) {
      alert("テスト期間を設定してください");
      return;
    }

    if (new Date(startDate) > new Date(endDate)) {
      alert("開始日は終了日より前の日付を入力してください");
      return;
    }

    if (selectedStores.length === 0) {
      alert("店舗が選択されていません");
      return;
    }

    if (selectedCategories.length === 0) {
      alert("商品カテゴリが未選択です");
      return;
    }

    // 進行状況表示
    const progressDiv = container.querySelector("#test-progress");
    progressDiv.classList.remove("hidden");

    try {
      // テスト実行のシミュレーション
      await new Promise(resolve => setTimeout(resolve, 3000));

      // 結果表示
      const mape = (Math.random() * 15 + 5).toFixed(2);
      const rmse = (Math.random() * 50 + 10).toFixed(2);
      const mae = (Math.random() * 30 + 5).toFixed(2);
      const r2 = (Math.random() * 0.3 + 0.7).toFixed(3);
      const executionTime = (Math.random() * 120 + 30).toFixed(1);

      container.querySelector("#metric-mape").textContent = mape;
      container.querySelector("#metric-rmse").textContent = rmse;
      container.querySelector("#metric-mae").textContent = mae;
      container.querySelector("#metric-r2").textContent = r2;
      container.querySelector("#execution-time").textContent = executionTime;

      // グラフ描画
      drawComparisonChart();

      // モデルパラメータ表示
      updateModelParameters(model);

      // テスト履歴に追加
      const testResult = {
        テスト日時: new Date().toLocaleString(),
        モデル名: model,
        テスト期間: `${startDate} ～ ${endDate}`,
        対象店舗数: selectedStores.length,
        MAPE: mape,
        RMSE: rmse,
        実行時間: executionTime
      };

      const saved = await window.aivicApi.save(testHistoryTableIndex, testResult);
      if (saved) {
        const updatedRows = await window.aivicApi.list(testHistoryTableIndex);
        if (updatedRows) renderTestHistory(updatedRows);
      }

    } catch (error) {
      alert("テスト実行中にエラーが発生しました: " + error.message);
    } finally {
      progressDiv.classList.add("hidden");
    }
  });

  // 6. グラフ描画関数
  function drawComparisonChart() {
    const canvas = container.querySelector("#comparison-chart");
    const ctx = canvas.getContext("2d");

    // Canvas サイズ設定
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    // グラフエリア設定
    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // サンプルデータ生成
    const dataPoints = 30;
    const actualData = [];
    const predictedData = [];

    for (let i = 0; i < dataPoints; i++) {
      const base = 100 + Math.sin(i * 0.2) * 30;
      actualData.push(base + (Math.random() - 0.5) * 20);
      predictedData.push(base + (Math.random() - 0.5) * 15);
    }

    // 背景クリア
    ctx.fillStyle = '#1a2332';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // 軸描画
    ctx.strokeStyle = '#4a5568';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(padding, padding);
    ctx.lineTo(padding, canvas.height - padding);
    ctx.lineTo(canvas.width - padding, canvas.height - padding);
    ctx.stroke();

    // 実績値線描画
    ctx.strokeStyle = '#3182ce';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < actualData.length; i++) {
      const x = padding + (i / (dataPoints - 1)) * chartWidth;
      const y = canvas.height - padding - (actualData[i] / 200) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 予測値線描画
    ctx.strokeStyle = '#e53e3e';
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < predictedData.length; i++) {
      const x = padding + (i / (dataPoints - 1)) * chartWidth;
      const y = canvas.height - padding - (predictedData[i] / 200) * chartHeight;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();

    // 凡例
    ctx.fillStyle = '#e2e8f0';
    ctx.font = '12px sans-serif';
    ctx.fillText('実績値', padding + 10, padding - 10);
    ctx.fillStyle = '#3182ce';
    ctx.fillRect(padding + 50, padding - 18, 15, 2);

    ctx.fillStyle = '#e2e8f0';
    ctx.fillText('予測値', padding + 80, padding - 10);
    ctx.fillStyle = '#e53e3e';
    ctx.fillRect(padding + 120, padding - 18, 15, 2);
  }

  // 7. モデルパラメータ更新関数
  function updateModelParameters(modelName) {
    const parametersDiv = container.querySelector("#model-parameters");
    const parameters = {
      'model-v1.0': {
        'アルゴリズム': 'LSTM',
        '学習データ期間': '過去24ヶ月',
        'エポック数': '100',
        'バッチサイズ': '32',
        '隠れ層数': '3',
        '正則化': 'L2 (0.001)'
      },
      'model-v1.1': {
        'アルゴリズム': 'LSTM + Attention',
        '学習データ期間': '過去36ヶ月',
        'エポック数': '150',
        'バッチサイズ': '64',
        '隠れ層数': '4',
        '正則化': 'Dropout (0.2)'
      },
      'model-v2.0': {
        'アルゴリズム': 'Transformer',
        '学習データ期間': '過去48ヶ月',
        'エポック数': '200',
        'バッチサイズ': '128',
        '隠れ層数': '6',
        '正則化': 'LayerNorm + Dropout'
      }
    };

    const params = parameters[modelName] || {};
    parametersDiv.innerHTML = Object.entries(params).map(([key, value]) => 
      `<div style="margin-bottom: 8px; color: var(--text);"><strong>${key}:</strong> ${value}</div>`
    ).join('');
  }

  // 8. エクスポートボタンの処理
  container.querySelector("#btn-export").addEventListener("click", async function() {
    const rows = await window.aivicApi.list(testHistoryTableIndex);
    if (!rows) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["テスト日時", "モデル名", "テスト期間", "対象店舗数", "MAPE", "RMSE", "実行時間"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...rows.map(row => [
        `"${row.テスト日時 || row.作成日時 || ''}"`,
        `"${row.モデル名 || row.予測モデルバージョン || ''}"`,
        `"${row.テスト期間 || ''}"`,
        row.対象店舗数 || '1',
        row.MAPE || '',
        row.RMSE || '',
        row.実行時間 || ''
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "model_test_results.csv";
    link.click();
  });

  // 9. 詳細ボタンのイベントデリゲーション
  container.addEventListener("click", function(e) {
    const detailBtn = e.target.closest(".view-detail-btn");
    if (detailBtn) {
      const testId = detailBtn.dataset.id;
      alert(`テスト詳細画面への遷移 (ID: ${testId})`);
    }
  });
}
